namespace Service.Tests;

public sealed class CodeGeneratorTests
{
    [Fact]
    public void Encode_of_zero_returns_zero()
    {
        string result = CodeGenerator.Encode(0);

        Assert.Equal("0", result);
    }

    [Fact]
    public void Encode_of_negative_returns_zero()
    {
        string result = CodeGenerator.Encode(-1);

        Assert.Equal("0", result);
    }

    [Fact]
    public void Encode_of_one_returns_one()
    {
        string result = CodeGenerator.Encode(1);

        Assert.Equal("1", result);
    }

    [Fact]
    public void Encode_of_nine_returns_nine()
    {
        string result = CodeGenerator.Encode(9);

        Assert.Equal("9", result);
    }

    [Fact]
    public void Encode_of_ten_returns_A()
    {
        string result = CodeGenerator.Encode(10);

        Assert.Equal("A", result);
    }

    [Fact]
    public void Encode_of_35_returns_Z()
    {
        string result = CodeGenerator.Encode(35);

        Assert.Equal("Z", result);
    }

    [Fact]
    public void Encode_of_36_returns_a()
    {
        string result = CodeGenerator.Encode(36);

        Assert.Equal("a", result);
    }

    [Fact]
    public void Encode_of_61_returns_z()
    {
        string result = CodeGenerator.Encode(61);

        Assert.Equal("z", result);
    }

    [Fact]
    public void Encode_of_62_returns_10()
    {
        string result = CodeGenerator.Encode(62);

        Assert.Equal("10", result);
    }

    [Fact]
    public void Encode_of_123_returns_1Z()
    {
        string result = CodeGenerator.Encode(123);

        Assert.Equal("1Z", result);
    }

    [Fact]
    public void Encode_is_monotonic_sequence()
    {
        string code1 = CodeGenerator.Encode(100);
        string code2 = CodeGenerator.Encode(101);
        string code3 = CodeGenerator.Encode(102);

        Assert.NotEqual(code1, code2);
        Assert.NotEqual(code2, code3);
        // The numeric ids are increasing, so encoded codes should be different
    }

    [Fact]
    public void Encode_of_large_id()
    {
        string result = CodeGenerator.Encode(long.MaxValue);

        Assert.NotEmpty(result);
        // Ensure it encodes without exception and produces a non-empty string
        Assert.True(result.All(c => "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz".Contains(c)));
    }

    [Fact]
    public void Encode_produces_base62_alphabet_only()
    {
        var ids = new[] { 1L, 10L, 35L, 36L, 61L, 62L, 100L };
        var validChars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

        foreach (long id in ids)
        {
            string code = CodeGenerator.Encode(id);
            Assert.True(code.All(c => validChars.Contains(c)), $"Code '{code}' contains invalid characters");
        }
    }
}
